    confirm() {}, // Removal requires authenticated lookup/mutation confirmation below.
    isStale: record => Boolean(record && now()-record.createdAt >= 7*86400000),
    getWarning: () => warning,
  };
  async function rawCall(name,args) {
    await guard(); const response = await client.rpc(name,args); await guard();
    if (response.error) { const e = new Error(response.error.message); e.code=response.error.code; e.uncertain=!response.status || response.status>=500 || !e.code; throw e; }
    return response.data;
  }
