import React, { useState } from 'react';
import { Trash2, Download, Send, BarChart2, ListFilter, Package, Layers } from 'lucide-react';
import { C, mono, btnGhost, CATEGORIES, todayStr } from '../theme';
import { DateRangePicker } from '../components/DateRangePicker';
import { toCSV, downloadCSV } from '../utils/csv';
import { sendToGoogleSheet } from '../utils/sheets';

export function ReportView({ transactions, onCancel, sheetsWebhookUrl }) {
  const [from, setFrom] = useState(todayStr());
  const [to, setTo] = useState(todayStr());
  const [activeTab, setActiveTab] = useState('dashboard');
  const [sendingProd, setSendingProd] = useState(false);
  const [sendingMat, setSendingMat] = useState(false);
  const [sendMsg, setSendMsg] = useState('');

  // แปลงฟอร์แมต YYYY-MM-DD -> DD/MM/YYYY
  const formatDateTH = (dateStr) => {
    if (!dateStr) return '';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  };

  // กรองตามวันที่เลือก + เรียงจากต้นเดือนไปสิ้นเดือน (เก่า -> ใหม่)
  const filtered = transactions
    .filter(t => {
      const date = t.created_at?.slice(0, 10);
      return date >= from && date <= to;
    })
    .sort((a, b) => (a.created_at || '').localeCompare(b.created_at || ''));

  // จัดกลุ่มออเดอร์ตามหมวดหมู่
  const byCategory = {};
  filtered.forEach(t => {
    if (!byCategory[t.category]) byCategory[t.category] = { total: 0, models: {}, txs: [] };
    byCategory[t.category].total += 1;
    byCategory[t.category].models[t.model_name] = (byCategory[t.category].models[t.model_name] || 0) + 1;
    byCategory[t.category].txs.push(t);
  });

  // เตรียมข้อมูล Export
  const rowsSummaryExport = () => {
    return filtered.map(t => ({
      วันที่: formatDateTH(t.created_at?.slice(0, 10)),
      เวลา: t.created_at?.slice(11, 16) || '',
      หมวดหมู่: t.category,
      รุ่นสินค้า: t.model_name,
      ออเดอร์: t.order_ref || '',
      ช่างผู้ผลิต: t.staff_name || '',
      จำนวน: 1
    }));
  };

  const rowsMaterialExport = () => {
    const matRows = [];
    filtered.forEach(t => {
      const dateFormatted = formatDateTH(t.created_at?.slice(0, 10));
      t.bom_snapshot?.forEach(b => {
        matRows.push({
          วันที่: dateFormatted,
          ชื่อวัตถุดิบ: b.material_name,
          จำนวนที่ใช้: b.qty,
          หน่วย: b.unit,
          รุ่นสินค้า: t.model_name,
          ออเดอร์: t.order_ref || ''
        });
      });
    });
    return matRows;
  };

  async function handleSendProdSheet() {
    setSendingProd(true);
    setSendMsg('กำลังส่งข้อมูลสินค้า...');
    const { error } = await sendToGoogleSheet(sheetsWebhookUrl, 'ProductionReport', rowsSummaryExport());
    setSendMsg(error || 'ส่งข้อมูลสินค้าเข้า Google Sheet เรียบร้อยแล้ว');
    setSendingProd(false);
  }

  async function handleSendMatSheet() {
    setSendingMat(true);
    setSendMsg('กำลังส่งข้อมูลวัตถุดิบ...');
    const { error } = await sendToGoogleSheet(sheetsWebhookUrl, 'MaterialsReport', rowsMaterialExport());
    setSendMsg(error || 'ส่งข้อมูลวัตถุดิบเข้า Google Sheet เรียบร้อยแล้ว');
    setSendingMat(false);
  }

  // สรุปยอดวัตถุดิบ
  const materialUsage = {};
  filtered.forEach(t => {
    t.bom_snapshot?.forEach(b => {
      if (!materialUsage[b.material_id]) {
        materialUsage[b.material_id] = { name: b.material_name, unit: b.unit, qty: 0 };
      }
      materialUsage[b.material_id].qty += b.qty;
    });
  });
  const materialList = Object.values(materialUsage).sort((a, b) => b.qty - a.qty);

  return (
    <div style={{ paddingBottom: 20 }}>
      <div style={{ fontSize: 15, fontWeight: 700, marginBottom: 10 }}>รายงานการผลิตและสรุปสต็อก</div>

      <DateRangePicker from={from} to={to} setFrom={setFrom} setTo={setTo} />

      {/* แท็บสลับหน้า */}
      <div style={{ display: 'flex', gap: 6, margin: '12px 0', background: C.panelAlt, padding: 3, borderRadius: 10 }}>
        <button 
          onClick={() => setActiveTab('dashboard')} 
          style={{ flex: 1, padding: '8px 0', border: 'none', borderRadius: 8, background: activeTab === 'dashboard' ? C.panel : 'transparent', color: activeTab === 'dashboard' ? C.amber : C.textDim, fontWeight: 700, fontSize: 12, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6 }}>
          <BarChart2 size={14} /> Dashboard สรุปยอด
        </button>
        <button 
          onClick={() => setActiveTab('raw')} 
          style={{ flex: 1, padding: '8px 0', border: 'none', borderRadius: 8, background: activeTab === 'raw' ? C.panel : 'transparent', color: activeTab === 'raw' ? C.amber : C.textDim, fontWeight: 700, fontSize: 12, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6 }}>
          <ListFilter size={14} /> รายการดิบ ({filtered.length})
        </button>
      </div>

      {/* ปุ่ม Export */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6, marginBottom: 10 }}>
        <button onClick={() => downloadCSV(`prod_${from}_to_${to}.csv`, toCSV(rowsSummaryExport(), ['วันที่', 'เวลา', 'หมวดหมู่', 'รุ่นสินค้า', 'ออเดอร์', 'ช่างผู้ผลิต', 'จำนวน']))} style={{ ...btnGhost, justifyContent: 'center', fontSize: 11 }}>
          <Download size={12} style={{ marginRight: 4 }} /> CSV สินค้า
        </button>
        <button onClick={() => downloadCSV(`mat_${from}_to_${to}.csv`, toCSV(rowsMaterialExport(), ['วันที่', 'ชื่อวัตถุดิบ', 'จำนวนที่ใช้', 'หน่วย', 'รุ่นสินค้า', 'ออเดอร์']))} style={{ ...btnGhost, justifyContent: 'center', fontSize: 11 }}>
          <Package size={12} style={{ marginRight: 4 }} /> CSV วัตถุดิบ
        </button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6, marginBottom: 14 }}>
        <button onClick={handleSendProdSheet} disabled={sendingProd} style={{ ...btnGhost, justifyContent: 'center', fontSize: 11, color: C.teal, borderColor: C.teal }}>
          <Send size={12} style={{ marginRight: 4 }} /> {sendingProd ? 'กำลังส่ง...' : 'Sheet สรุปสินค้า'}
        </button>
        <button onClick={handleSendMatSheet} disabled={sendingMat} style={{ ...btnGhost, justifyContent: 'center', fontSize: 11, color: C.teal, borderColor: C.teal }}>
          <Send size={12} style={{ marginRight: 4 }} /> {sendingMat ? 'กำลังส่ง...' : 'Sheet สรุปวัตถุดิบ'}
        </button>
      </div>

      {sendMsg && <div style={{ fontSize: 11.5, color: sendMsg.includes('เรียบร้อย') ? C.teal : C.red, marginBottom: 10, textAlign: 'center' }}>{sendMsg}</div>}

      {/* TAB 1: DASHBOARD */}
      {activeTab === 'dashboard' && (
        <div>
          {/* การ์ดสรุปแยกตามหมวดหมู่ (โทนสีธีมเดิม) */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(80px, 1fr))', gap: 8, marginBottom: 16 }}>
            {CATEGORIES.map(cat => {
              const count = byCategory[cat]?.total || 0;
              return (
                <div key={cat} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: '12px 6px', textAlign: 'center' }}>
                  <div style={{ fontSize: 11, color: C.textDim, fontWeight: 600, marginBottom: 4 }}>{cat}</div>
                  <div style={{ fontSize: 22, fontWeight: 800, color: count > 0 ? C.amber : C.text, ...mono }}>{count}</div>
                </div>
              );
            })}
          </div>

          <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}>
            <Layers size={14} color={C.amber} /> สรุปยอดตามหมวดหมู่และรุ่น
          </div>
          {Object.keys(byCategory).length === 0 && (
            <div style={{ fontSize: 12, color: C.textDim, textAlign: 'center', padding: '15px 0' }}>ไม่มีรายการในช่วงวันที่เลือก</div>
          )}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 20 }}>
            {CATEGORIES.filter(cat => byCategory[cat]).map(cat => {
              const data = byCategory[cat];
              return (
                <div key={cat} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 10, padding: 12 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                    <span style={{ fontWeight: 700, fontSize: 12.5, color: C.amber }}>{cat}</span>
                    <span style={{ ...mono, fontWeight: 700, fontSize: 12, color: C.text }}>รวม {data.total} ชิ้น</span>
                  </div>
                  <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                    {Object.entries(data.models).map(([model, count]) => (
                      <div key={model} style={{ background: C.panelAlt, border: `1px solid ${C.line}`, borderRadius: 6, padding: '4px 8px', fontSize: 11 }}>
                        {model} <span style={{ ...mono, color: C.teal, fontWeight: 700 }}>x{count}</span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>

          <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 8, display: 'flex', alignItems: 'center', gap: 6 }}>
            <Package size={14} color={C.teal} /> สรุปการใช้วัตถุดิบรวม
          </div>
          {materialList.length === 0 ? (
            <div style={{ fontSize: 12, color: C.textDim, textAlign: 'center', padding: '15px 0' }}>ไม่มีการเบิกใช้วัตถุดิบในช่วงนี้</div>
          ) : (
            <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 10, padding: 10 }}>
              {materialList.map((m, idx) => (
                <div key={idx} style={{ display: 'flex', justifyContent: 'space-between', padding: '6px 0', borderBottom: idx < materialList.length - 1 ? `1px solid ${C.line}` : 'none', fontSize: 11.5 }}>
                  <span style={{ color: C.text }}>{m.name}</span>
                  <span style={{ ...mono, fontWeight: 700, color: C.teal }}>{m.qty} {m.unit}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* TAB 2: รายการดิบ */}
      {activeTab === 'raw' && (
        <div>
          {filtered.length === 0 && <div style={{ fontSize: 13, color: C.textDim, textAlign: 'center', padding: '20px 0' }}>ไม่มีรายการในช่วงนี้</div>}
          {CATEGORIES.filter(cat => byCategory[cat]).map(cat => {
            const txs = byCategory[cat].txs;
            return (
              <div key={cat} style={{ marginBottom: 16 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: C.amber }}>{cat}</div>
                  <div style={{ fontSize: 11.5, color: C.textDim, ...mono }}>{txs.length} ชิ้น</div>
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 5 }}>
                  {txs.map(t => (
                    <div key={t.id} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 9, padding: '8px 10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 6 }}>
                      <div style={{ minWidth: 0 }}>
                        <div style={{ fontSize: 12, fontWeight: 600 }}>{t.model_name}</div>
                        <div style={{ fontSize: 10.5, color: C.textDim, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>ออเดอร์ {t.order_ref} · ช่าง {t.staff_name} · {formatDateTH(t.created_at.slice(0, 10))}</div>
                        {t.note && <div style={{ fontSize: 10.5, color: C.amber, marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>เหตุผล: {t.note}</div>}
                      </div>
                      <button onClick={() => onCancel(t)} style={{ background: 'none', border: `1px solid ${C.line}`, borderRadius: 7, padding: 5, color: C.red, cursor: 'pointer', display: 'flex', flexShrink: 0 }}>
                        <Trash2 size={12} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

src/views/SettingsView.jsx:
import React, { useEffect, useState } from 'react';
import { Save, Users } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';
import { C, inputStyle, btnPrimary } from '../theme';

export function SettingsView({ webhookUrl, onSaveWebhook }) {
  const [url, setUrl] = useState(webhookUrl || '');
  const [saving, setSaving] = useState(false);
  const [savedMsg, setSavedMsg] = useState('');
  const [profiles, setProfiles] = useState([]);
  const [loadingProfiles, setLoadingProfiles] = useState(true);

  useEffect(() => {
    supabase.from('profiles').select('*').order('full_name').then(({ data }) => {
      setProfiles(data || []);
      setLoadingProfiles(false);
    });
  }, []);

  async function saveWebhook() {
    setSaving(true);
    await onSaveWebhook(url.trim());
    setSavedMsg('บันทึกแล้ว');
    setSaving(false);
    setTimeout(() => setSavedMsg(''), 2000);
  }

  async function changeRole(id, role) {
    await supabase.from('profiles').update({ role }).eq('id', id);
    setProfiles(profiles.map(p => p.id === id ? { ...p, role } : p));
  }

  return (
    <div>
      <div style={{ fontSize: 15, fontWeight: 700, marginBottom: 12 }}>ตั้งค่า (หัวหน้าช่างเท่านั้น)</div>

      <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14, marginBottom: 16 }}>
        <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 6 }}>Google Sheets Webhook URL</div>
        <div style={{ fontSize: 11.5, color: C.textDim, marginBottom: 8, lineHeight: 1.5 }}>
          URL จาก Google Apps Script ที่ deploy เป็น Web App (ดูวิธีตั้งค่าใน README.md หัวข้อ "Google Sheets sync")
        </div>
        <input style={inputStyle} value={url} onChange={e => setUrl(e.target.value)} placeholder="https://script.google.com/macros/s/.../exec" />
        <button onClick={saveWebhook} disabled={saving} style={{ ...btnPrimary, marginTop: 8, width: '100%' }}>
          <Save size={14} style={{ marginRight: 6 }} /> {saving ? 'กำลังบันทึก...' : 'บันทึก URL'}
        </button>
        {savedMsg && <div style={{ fontSize: 11.5, color: C.teal, marginTop: 6, textAlign: 'center' }}>{savedMsg}</div>}
      </div>

      <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 13, fontWeight: 700, marginBottom: 10 }}>
          <Users size={14} /> ผู้ใช้งานและสิทธิ์
        </div>
        <div style={{ fontSize: 11, color: C.textDim, marginBottom: 10, lineHeight: 1.5 }}>
          การสร้างบัญชีใหม่ทำใน Supabase Dashboard → Authentication → Users → Add user
          (มีแค่คุณที่เข้าถึง Dashboard ได้) จากนั้นตั้งสิทธิ์ให้แต่ละคนได้ที่นี่
        </div>
        {loadingProfiles && <div style={{ fontSize: 12, color: C.textDim }}>กำลังโหลด...</div>}
        {profiles.map(p => (
          <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderTop: `1px solid ${C.line}` }}>
            <div style={{ fontSize: 12.5 }}>{p.full_name}</div>
            <select value={p.role} onChange={e => changeRole(p.id, e.target.value)} style={{ ...inputStyle, width: 130 }}>
              <option value="staff">ทีมผลิต (staff)</option>
              <option value="purchasing">จัดซื้อ (purchasing)</option>
              <option value="admin">หัวหน้าช่าง (admin)</option>
            </select>
          </div>
        ))}
      </div>
    </div>
  );
}

src/views/StockView.jsx:
import React, { useState } from 'react';
import { Plus, PackagePlus, ChevronRight, ChevronDown, History, ArrowDownCircle, ArrowUpCircle, Download, Send, Search, BookOpen } from 'lucide-react';
import { C, mono, btnGhost, tabBtn, tabBtnActive, todayStr } from '../theme';
import { DateRangePicker } from '../components/DateRangePicker';
import { toCSV, downloadCSV } from '../utils/csv';
import { sendToGoogleSheet } from '../utils/sheets';

export function StockView({ materials = [], stockLog = [], transactions = [], role, onEdit, onAdd, onRestock, sheetsWebhookUrl }) {
  const [sub, setSub] = useState('current');
  const [search, setSearch] = useState('');
  const [balanceSearch, setBalanceSearch] = useState('');
  const [from, setFrom] = useState(todayStr());
  const [to, setTo] = useState(todayStr());
  const [sending, setSending] = useState(false);
  const [sendMsg, setSendMsg] = useState('');
  const [balSending, setBalSending] = useState(false);
  const [balSendMsg, setBalSendMsg] = useState('');
  const [expanded, setExpanded] = useState(null);

  const isTypeIn = (l) => l.type === 'in';

  // ใช้ BOM ทุกบรรทัดและวันที่สร้างรายการเช่นเดียวกับหน้ารายงาน
  const txLogs = transactions.flatMap(tx =>
    (tx.bom_snapshot || []).map((b, index) => ({
      id: `tx_${tx.id}_${index}`,
      created_at: tx.created_at,
      type: 'out',
      material_id: b.material_id,
      material_name: b.material_name,
      amount: Number(b.qty || 0),
      unit: b.unit,
      order_ref: tx.order_ref,
      staff_name: tx.staff_name,
    }))
  );

  // รับเฉพาะซื้อเข้า ไม่รวม log เบิกหรือคืนที่ซ้ำกับยอดตามรายงาน
  const purchaseLogs = stockLog.filter(
    l => l.type === 'in' && l.order_ref === 'ซื้อเข้า'
  );
  const combinedLogs = [...purchaseLogs, ...txLogs];
  // กรอง Log ตามช่วงวันที่
  const filteredStockLog = combinedLogs.filter(l => {
    const d = l.created_at?.slice(0, 10);
    return d >= from && d <= to;
  });

  const restockCount = filteredStockLog.filter(l => isTypeIn(l)).length;

  // ------------------ 1. จัดกลุ่มรับเข้า–เบิกตามรายงาน ------------------
  const byMaterial = {};
  filteredStockLog.forEach(l => {
    const key = String(l.material_id);

    if (!byMaterial[key]) {
      byMaterial[key] = { 
        id: key, 
        name: l.material_name || 'ไม่ระบุ', 
        unit: l.unit || '', 
        in: 0, 
        out: 0, 
        entries: [] 
      };
    }
    const amt = Number(l.amount) || 0;
    if (isTypeIn(l)) {
      byMaterial[key].in += amt;
    } else {
      byMaterial[key].out += amt;
    }
    byMaterial[key].entries.push(l);
  });

  const materialRows = Object.values(byMaterial)
    .map(v => ({ ...v, entries: v.entries.sort((a, b) => new Date(b.created_at) - new Date(a.created_at)) }))
    .sort((a, b) => a.name.localeCompare(b.name, 'th'));

  const rowsForExport = () => filteredStockLog.map(l => ({
    วันที่: l.created_at?.slice(0, 10) || '',
    ประเภท: isTypeIn(l) ? 'รับเข้า' : 'เบิกออก',
    วัตถุดิบ: l.material_name || '',
    จำนวน: l.amount || 0,
    หน่วย: l.unit || '',
    อ้างอิง: l.order_ref || '',
    ผู้ทำรายการ: l.staff_name || '',
  }));

  async function handleSendToSheet() {
    setSending(true); setSendMsg('');
    const { error } = await sendToGoogleSheet(sheetsWebhookUrl, 'StockLog', rowsForExport());
    setSendMsg(error || 'ส่งเข้า Google Sheet แล้ว');
    setSending(false);
  }

// ------------------ 2. ต้นงวด-ปลายงวด (Balance Calculation - Fixed) ------------------
  const balanceRows = materials
    .filter(m => m.name.toLowerCase().includes(balanceSearch.trim().toLowerCase()))
    .map(m => {
      const matId = String(m.id);
      const logsForMat = combinedLogs.filter(
        l => String(l.material_id) === matId
      );

      // แยก Log ก่อนช่วงเวลา, ในช่วงเวลา, และหลังช่วงเวลา
      const before = logsForMat.filter(l => (l.created_at?.slice(0, 10) || '') < from);
      const within = logsForMat.filter(l => {
        const d = l.created_at?.slice(0, 10) || '';
        return d >= from && d <= to;
      });

      // รวมยอดรับเข้าและเบิกตามรายงานในช่วงที่เลือก
      const inWithin = within.filter(l => isTypeIn(l)).reduce((s, l) => s + (Number(l.amount) || 0), 0);
      const outWithin = within.filter(l => !isTypeIn(l)).reduce((s, l) => s + (Number(l.amount) || 0), 0);

      // ยอดเบิกทั้งหมดของวัตถุดิบนี้
      const totalOutForMat = logsForMat.filter(l => !isTypeIn(l)).reduce((s, l) => s + (Number(l.amount) || 0), 0);
      const totalInForMat = logsForMat.filter(l => isTypeIn(l)).reduce((s, l) => s + (Number(l.amount) || 0), 0);

      // รวมการเคลื่อนไหวก่อนช่วงที่เลือก
      const inBefore = before.filter(l => isTypeIn(l)).reduce((s, l) => s + (Number(l.amount) || 0), 0);
      const outBefore = before.filter(l => !isTypeIn(l)).reduce((s, l) => s + (Number(l.amount) || 0), 0);

      // ย้อนฐานจากยอดปัจจุบัน รวมกรณียอดเป็นศูนย์หรือติดลบ
      const currentQty = Number(m.qty ?? 0);
      const baseStock = currentQty + totalOutForMat - totalInForMat;

      // ต้นงวด = ยอดตั้งต้น + ยอดรับก่อนหน้า - ยอดเบิกรวมก่อนหน้า
      const opening = baseStock + inBefore - outBefore;
      // ปลายงวด = ต้นงวด + รับเข้า - เบิกออก
      const closing = opening + inWithin - outWithin;

      return { id: m.id, name: m.name, unit: m.unit, opening, inWithin, outWithin, closing };
    })
    .sort((a, b) => a.name.localeCompare(b.name, 'th'));

  const balanceRowsForExport = () => balanceRows.map(r => ({
    วัตถุดิบ: r.name, หน่วย: r.unit, ต้นงวด: r.opening, รับเข้า: r.inWithin, เบิกออก: r.outWithin, ปลายงวด: r.closing,
  }));

  async function handleSendBalanceToSheet() {
    setBalSending(true); setBalSendMsg('');
    const { error } = await sendToGoogleSheet(sheetsWebhookUrl, 'StockBalance', balanceRowsForExport());
    setBalSendMsg(error || 'ส่งเข้า Google Sheet แล้ว');
    setBalSending(false);
  }

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
        <div style={{ fontSize: 15, fontWeight: 700 }}>
          {sub === 'current' ? `คลังวัตถุดิบ (${materials.length})` : sub === 'history' ? 'รับเข้า–เบิกตามรายงาน' : 'ต้นงวด-ปลายงวด'}
        </div>
        {sub === 'current' && role === 'admin' && <button onClick={onAdd} style={btnGhost}><Plus size={13} style={{ marginRight: 4 }} /> เพิ่มรายการ</button>}
      </div>

      {role === 'admin' && (
        <div style={{ display: 'flex', gap: 6, marginBottom: 12, flexWrap: 'wrap' }}>
          <button onClick={() => setSub('current')} style={{ ...tabBtn, ...(sub === 'current' ? tabBtnActive : {}) }}>รายการปัจจุบัน</button>
          <button onClick={() => setSub('history')} style={{ ...tabBtn, ...(sub === 'history' ? tabBtnActive : {}) }}><History size={12} style={{ marginRight: 4 }} />รับเข้า–เบิกตามรายงาน</button>
          <button onClick={() => setSub('balance')} style={{ ...tabBtn, ...(sub === 'balance' ? tabBtnActive : {}) }}><BookOpen size={12} style={{ marginRight: 4 }} />ต้นงวด-ปลายงวด</button>
        </div>
      )}

      {sub !== 'current' && role === 'admin' && (
        <div style={{ fontSize: 10, color: C.textDim, marginBottom: 8 }}>
          ยอดเบิกอ้างอิงวันที่สร้างรายการ เช่นเดียวกับหน้ารายงาน
        </div>
      )}

      {sub === 'current' && (
        <div>
          <div style={{ position: 'relative', marginBottom: 10 }}>
            <Search size={14} color={C.textDim} style={{ position: 'absolute', left: 10, top: 10 }} />
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="ค้นหาวัตถุดิบ..."
              style={{ width: '100%', background: C.panelAlt, border: `1px solid ${C.line}`, borderRadius: 8, padding: '8px 10px 8px 32px', color: C.text, fontSize: 13, boxSizing: 'border-box' }} />
          </div>
          <div className="grid-list">
            {materials.filter(m => m.name.toLowerCase().includes(search.trim().toLowerCase())).map(m => (
              <div key={m.id} style={{ background: m.qty <= 2 ? 'rgba(217,119,87,0.08)' : C.panel, border: `1px solid ${C.line}`, borderRadius: 10, padding: '10px 12px', display: 'flex', alignItems: 'center', gap: 8 }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 12.5, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{m.name}</div>
                  <div style={{ fontSize: 11, marginTop: 2, ...mono, color: m.qty <= 2 ? C.red : C.teal, fontWeight: 700 }}>{m.qty} {m.unit}</div>
                </div>
                <button onClick={() => onRestock(m)} title="รับของเข้าคลัง"
                  style={{ background: 'rgba(63,167,150,0.14)', border: `1px solid ${C.teal}`, borderRadius: 8, padding: '6px 9px', cursor: 'pointer', color: C.teal, display: 'flex', alignItems: 'center', flexShrink: 0 }}>
                  <PackagePlus size={14} />
                </button>
                {role === 'admin' && (
                  <button onClick={() => onEdit(m)} style={{ background: 'none', border: 'none', color: C.textDim, cursor: 'pointer', flexShrink: 0 }}><ChevronRight size={16} /></button>
                )}
              </div>
            ))}
            {materials.filter(m => m.name.toLowerCase().includes(search.trim().toLowerCase())).length === 0 && (
              <div style={{ fontSize: 13, color: C.textDim, textAlign: 'center', padding: '20px 0' }}>ไม่พบวัตถุดิบที่ค้นหา</div>
            )}
          </div>
        </div>
      )}

      {sub === 'history' && role === 'admin' && (
        <div>
          <DateRangePicker from={from} to={to} setFrom={setFrom} setTo={setTo} />
          <div style={{ display: 'flex', gap: 8, margin: '12px 0' }}>
            <button onClick={() => downloadCSV(`stock-report_${from}_to_${to}.csv`, toCSV(rowsForExport(), ['วันที่', 'ประเภท', 'วัตถุดิบ', 'จำนวน', 'หน่วย', 'อ้างอิง', 'ผู้ทำรายการ']))} style={{ ...btnGhost, flex: 1, justifyContent: 'center' }}>
              <Download size={13} style={{ marginRight: 4 }} /> ส่งออก CSV
            </button>
            <button onClick={handleSendToSheet} disabled={sending} style={{ ...btnGhost, flex: 1, justifyContent: 'center' }}>
              <Send size={13} style={{ marginRight: 4 }} /> {sending ? 'กำลังส่ง...' : 'ส่งเข้า Google Sheet'}
            </button>
          </div>
          {sendMsg && <div style={{ fontSize: 11.5, color: sendMsg.includes('แล้ว') ? C.teal : C.red, marginBottom: 10 }}>{sendMsg}</div>}

          <div style={{ marginBottom: 12 }}>
            <div style={{ background: 'rgba(63,167,150,0.1)', border: `1px solid ${C.teal}`, borderRadius: 10, padding: '12px 16px' }}>
              <div style={{ fontSize: 11, color: C.textDim }}>รับเข้า (ซื้อเข้าจริง)</div>
              <div style={{ fontSize: 20, fontWeight: 800, color: C.teal, ...mono, marginTop: 2 }}>{restockCount} ครั้ง</div>
            </div>
          </div>

          <div style={{ fontSize: 11.5, color: C.textDim, marginBottom: 8 }}>แตะแต่ละรายการเพื่อดูรายละเอียดย่อย</div>

          {materialRows.length === 0 && <div style={{ fontSize: 13, color: C.textDim, textAlign: 'center', padding: '20px 0' }}>ไม่มีรายการในช่วงนี้</div>}

          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {materialRows.map(r => {
              const isOpen = expanded === r.id;
              return (
                <div key={r.id} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 10, overflow: 'hidden' }}>
                  <button onClick={() => setExpanded(isOpen ? null : r.id)}
                    style={{ all: 'unset', display: 'flex', alignItems: 'center', gap: 8, width: '100%', boxSizing: 'border-box', padding: '10px 12px', cursor: 'pointer' }}>
                    <ChevronDown size={14} color={C.textDim} style={{ flexShrink: 0, transform: isOpen ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s' }} />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 12.5, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{r.name}</div>
                      <div style={{ fontSize: 10.5, color: C.textDim }}>{r.entries.length} รายการ</div>
                    </div>
                    <div style={{ display: 'flex', gap: 10, flexShrink: 0 }}>
                      {r.in > 0 && <span style={{ ...mono, fontSize: 12, fontWeight: 700, color: C.teal }}>+{r.in}</span>}
                      {r.out > 0 && <span style={{ ...mono, fontSize: 12, fontWeight: 700, color: C.red }}>-{r.out}</span>}
                      <span style={{ fontSize: 11, color: C.textDim }}>{r.unit}</span>
                    </div>
                  </button>
                  {isOpen && (
                    <div style={{ borderTop: `1px solid ${C.line}`, padding: '4px 12px 8px' }}>
                      {r.entries.map((l, idx) => {
                        const in_ = isTypeIn(l);
                        return (
                          <div key={l.id || idx} style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 0', borderBottom: `1px solid ${C.line}` }}>
                            {in_ ? <ArrowDownCircle size={13} color={C.teal} /> : <ArrowUpCircle size={13} color={C.red} />}
                            <div style={{ flex: 1, minWidth: 0 }}>
                              <div style={{ fontSize: 11, color: C.textDim, ...mono }}>{l.created_at?.slice(0, 10)}</div>
                              <div style={{ fontSize: 11, color: C.textDim, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{l.order_ref}{l.staff_name ? ` · ${l.staff_name}` : ''}</div>
                            </div>
                            <div style={{ ...mono, fontSize: 12, fontWeight: 700, color: in_ ? C.teal : C.red, flexShrink: 0 }}>
                              {in_ ? '+' : '-'}{l.amount} {l.unit}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {sub === 'balance' && role === 'admin' && (
        <div>
          <DateRangePicker from={from} to={to} setFrom={setFrom} setTo={setTo} />
          <div style={{ fontSize: 10, color: C.textDim, margin: '8px 0 12px', lineHeight: 1.5 }}>
            ต้นงวด = ยอดคงเหลือก่อนเริ่มช่วงที่เลือก · ปลายงวด = ยอดคงเหลือ ณ สิ้นช่วงที่เลือก
          </div>
          <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
            <button onClick={() => downloadCSV(`stock-balance_${from}_to_${to}.csv`, toCSV(balanceRowsForExport(), ['วัตถุดิบ', 'หน่วย', 'ต้นงวด', 'รับเข้า', 'เบิกออก', 'ปลายงวด']))} style={{ ...btnGhost, flex: 1, justifyContent: 'center' }}>
              <Download size={13} style={{ marginRight: 4 }} /> ส่งออก CSV
            </button>
            <button onClick={handleSendBalanceToSheet} disabled={balSending} style={{ ...btnGhost, flex: 1, justifyContent: 'center' }}>
              <Send size={13} style={{ marginRight: 4 }} /> {balSending ? 'กำลังส่ง...' : 'ส่งเข้า Google Sheet'}
            </button>
          </div>
          {balSendMsg && <div style={{ fontSize: 11.5, color: balSendMsg.includes('แล้ว') ? C.teal : C.red, marginBottom: 10 }}>{balSendMsg}</div>}

          <div style={{ position: 'relative', marginBottom: 12 }}>
            <Search size={14} color={C.textDim} style={{ position: 'absolute', left: 10, top: 10 }} />
            <input value={balanceSearch} onChange={e => setBalanceSearch(e.target.value)} placeholder="ค้นหาวัตถุดิบ..."
              style={{ width: '100%', background: C.panelAlt, border: `1px solid ${C.line}`, borderRadius: 8, padding: '8px 10px 8px 32px', color: C.text, fontSize: 13, boxSizing: 'border-box' }} />
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {balanceRows.map(r => (
              <div key={r.id} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 10, padding: '10px 12px' }}>
                <div style={{ fontSize: 12.5, fontWeight: 600, marginBottom: 8, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{r.name}</div>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 6, textAlign: 'center' }}>
                  <div>
                    <div style={{ fontSize: 9.5, color: C.textDim }}>ต้นงวด</div>
                    <div style={{ ...mono, fontSize: 12.5, fontWeight: 700 }}>{r.opening}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: 9.5, color: C.textDim }}>รับเข้า</div>
                    <div style={{ ...mono, fontSize: 12.5, fontWeight: 700, color: C.teal }}>+{r.inWithin}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: 9.5, color: C.textDim }}>เบิกออก</div>
                    <div style={{ ...mono, fontSize: 12.5, fontWeight: 700, color: C.red }}>-{r.outWithin}</div>
                  </div>
                  <div>
                    <div style={{ fontSize: 9.5, color: C.textDim }}>ปลายงวด</div>
                    <div style={{ ...mono, fontSize: 12.5, fontWeight: 700, color: C.amber }}>{r.closing}</div>
                  </div>
                </div>
                <div style={{ textAlign: 'right', fontSize: 10, color: C.textDim, marginTop: 4 }}>{r.unit}</div>
              </div>
            ))}
            {balanceRows.length === 0 && <div style={{ fontSize: 13, color: C.textDim, textAlign: 'center', padding: '20px 0' }}>ไม่พบวัตถุดิบที่ค้นหา</div>}
          </div>
        </div>
      )}
    </div>
  );
}
